-- Apply after supabase/schema.sql. This migration removes demo-only authorization assumptions.
begin;
create extension if not exists pgcrypto;
create unique index if not exists one_admin_profile_only on public.profiles ((role)) where role='admin';
create sequence if not exists public.book_request_number_seq;
create sequence if not exists public.waste_request_number_seq;
alter table public.profiles add column if not exists suspended_at timestamptz;
alter table public.book_requests add column if not exists final_offer_amount numeric(10,2);
alter table public.book_requests add column if not exists final_offer_reason text;
alter table public.book_requests add column if not exists final_offer_accepted_at timestamptz;
alter table public.waste_requests add column if not exists final_offer_amount numeric(10,2);
alter table public.waste_requests add column if not exists final_offer_reason text;
alter table public.waste_requests add column if not exists final_offer_accepted_at timestamptz;
alter table public.waste_requests add constraint waste_minimum_weight_check check(estimated_weight_kg>=10.0);
create table if not exists public.user_roles(user_id uuid primary key references public.profiles(id) on delete cascade,role text not null check(role in ('seller','book_stall','raddi_owner','admin')),created_at timestamptz not null default now());
create table if not exists public.conversations(id uuid primary key default gen_random_uuid(),request_type text not null check(request_type in ('book','raddi')),book_request_id uuid references public.book_requests(id) on delete cascade,waste_request_id uuid references public.waste_requests(id) on delete cascade,seller_id uuid not null references public.profiles(id),partner_id uuid not null references public.profiles(id),created_at timestamptz not null default now(),check(num_nonnulls(book_request_id,waste_request_id)=1),unique(book_request_id),unique(waste_request_id));
create table if not exists public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 4000),read_at timestamptz,created_at timestamptz not null default now());
create index if not exists messages_conversation_idx on public.messages(conversation_id,created_at);
create table if not exists public.guidelines(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,body text not null,page_key text not null,is_published boolean not null default false,updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());
create table if not exists public.announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,page_key text not null,is_published boolean not null default false,starts_at timestamptz,ends_at timestamptz,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table if not exists public.transactions(id uuid primary key default gen_random_uuid(),request_type text not null check(request_type in ('book','raddi')),book_request_id uuid references public.book_requests(id) on delete cascade,waste_request_id uuid references public.waste_requests(id) on delete cascade,offer_id uuid not null unique references public.offers(id),seller_id uuid not null references public.profiles(id),partner_id uuid not null references public.profiles(id),status text not null default 'Accepted',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(num_nonnulls(book_request_id,waste_request_id)=1),unique(book_request_id),unique(waste_request_id));
create table if not exists public.admin_audit_logs(id uuid primary key default gen_random_uuid(),admin_id uuid not null references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.book_images(id uuid primary key default gen_random_uuid(),book_item_id uuid not null references public.book_items(id) on delete cascade,kind text not null check(kind in ('front','back','inside')),storage_path text not null unique,created_at timestamptz not null default now(),unique(book_item_id,kind));
create table if not exists public.scrap_images(id uuid primary key default gen_random_uuid(),waste_request_id uuid not null references public.waste_requests(id) on delete cascade,storage_path text not null unique,created_at timestamptz not null default now());

-- Secure role lookup. Admin is never accepted from public signup metadata.
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and p.role='admin' and p.suspended_at is null and p.is_verified) $$;
create or replace function public.create_profile_from_auth() returns trigger language plpgsql security definer set search_path=public,auth as $$
declare requested_role text; business_name text; business_address text; business_pin text; business_license text; phone text;
begin
 requested_role:=coalesce(new.raw_user_meta_data->>'role','seller');
 if requested_role not in ('seller','book_stall','raddi_owner') then requested_role:='seller'; end if;
 phone:=coalesce(new.raw_user_meta_data->>'phone_number','');
 insert into public.profiles(id,email,full_name,phone_number,role,is_verified,age_confirmed)
 values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',''),phone,requested_role, new.email_confirmed_at is not null,(new.raw_user_meta_data->>'age_confirmed'='true'));
 insert into public.user_roles(user_id,role) values(new.id,requested_role);
 business_name:=nullif(trim(new.raw_user_meta_data->>'business_name'),''); business_address:=nullif(trim(new.raw_user_meta_data->>'business_address'),''); business_pin:=nullif(trim(new.raw_user_meta_data->>'business_pin'),''); business_license:=nullif(trim(new.raw_user_meta_data->>'business_license'),'');
 if requested_role='book_stall' and business_name is not null and business_address is not null and business_pin ~ '^[1-9][0-9]{5}$' then
  insert into public.book_stalls(user_id,stall_name,shop_licence_or_gst,address,pin_code,contact_phone,contact_email,admin_approval_status) values(new.id,business_name,business_license,business_address,business_pin,phone,new.email,'pending');
 elsif requested_role='raddi_owner' and business_name is not null and business_address is not null and business_pin ~ '^[1-9][0-9]{5}$' then
  insert into public.raddi_owners(user_id,business_name,licence_number,base_address,operating_pin_codes,contact_phone,contact_email,admin_approval_status) values(new.id,business_name,business_license,business_address,array[business_pin],phone,new.email,'pending');
 end if;
 return new;
end $$;
drop trigger if exists second_shelf_auth_profile on auth.users;
create trigger second_shelf_auth_profile after insert on auth.users for each row execute function public.create_profile_from_auth();
create or replace function public.sync_auth_verification() returns trigger language plpgsql security definer set search_path=public as $$ begin update public.profiles set is_verified=(new.email_confirmed_at is not null),updated_at=now() where id=new.id;return new;end $$;
drop trigger if exists second_shelf_email_verified on auth.users;
create trigger second_shelf_email_verified after update of email_confirmed_at on auth.users for each row execute function public.sync_auth_verification();
create or replace function public.set_request_number() returns trigger language plpgsql set search_path=public as $$ begin if new.request_number is null or new.request_number='' then if tg_table_name='book_requests' then new.request_number:='BOK-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.book_request_number_seq')::text,6,'0');else new.request_number:='RAD-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.waste_request_number_seq')::text,6,'0');end if;end if;return new;end $$;
alter table public.book_requests alter column request_number set default '';
alter table public.waste_requests alter column request_number set default '';
drop trigger if exists generate_book_request_number on public.book_requests;create trigger generate_book_request_number before insert on public.book_requests for each row execute function public.set_request_number();
drop trigger if exists generate_waste_request_number on public.waste_requests;create trigger generate_waste_request_number before insert on public.waste_requests for each row execute function public.set_request_number();
create or replace function public.calculate_book_item_estimate() returns trigger language plpgsql security definer set search_path=public as $$ declare pct numeric;begin select max_percentage into pct from public.valuation_rules where condition_name=new.condition;if pct is null then raise exception 'Missing active valuation rule';end if;new.estimated_item_payout:=round(new.original_price*pct/100*new.number_of_copies,2);return new;end $$;
drop trigger if exists book_item_estimate on public.book_items;create trigger book_item_estimate before insert or update of original_price,condition,number_of_copies on public.book_items for each row execute function public.calculate_book_item_estimate();
create or replace function public.enforce_offer_cap_and_approval() returns trigger language plpgsql security definer set search_path=public as $$ declare req public.book_requests; waste public.waste_requests; owner_ok boolean; cap numeric;begin
 if new.request_type='book' then
  select * into req from public.book_requests where id=new.book_request_id;
  select exists(select 1 from public.book_stalls where id=new.stall_id and admin_approval_status='approved') into owner_ok;
  if not owner_ok or req.status not in ('Pending','Offer Received','Offer Revised') then raise exception 'Only an approved stall may offer on an open book request';end if;
  select coalesce(sum(i.estimated_item_payout),0) into cap from public.book_items i where i.book_request_id=req.id;
  if new.offered_amount>cap then raise exception 'Offer exceeds the server calculated condition cap';end if;if new.offered_amount<cap and nullif(trim(new.revision_reason),'') is null then raise exception 'Offers below the estimate require a written reason';end if;
  if tg_op='UPDATE' and new.offered_amount<old.offered_amount and nullif(trim(new.revision_reason),'') is null then raise exception 'A lower or revised offer requires a written reason';end if;
 else
  select * into waste from public.waste_requests where id=new.waste_request_id;
  select exists(select 1 from public.raddi_owners where id=new.raddi_owner_id and admin_approval_status='approved') into owner_ok;
  if not owner_ok or waste.status not in ('Pending','Offer Received') or waste.estimated_weight_kg<10 then raise exception 'Only an approved recycler may offer on an eligible request';end if;
  if new.offered_rate_per_kg is null or new.offered_rate_per_kg<=0 then raise exception 'Rate per kg must be positive';end if;
  new.offered_amount:=round(waste.estimated_weight_kg*new.offered_rate_per_kg,2);
 end if;return new;end $$;
drop trigger if exists enforce_offer_cap on public.offers;create trigger enforce_offer_cap before insert or update of offered_amount,offered_rate_per_kg,revision_reason,offer_status on public.offers for each row execute function public.enforce_offer_cap_and_approval();

-- Safe request feeds: private address and phone columns are never present in these views.
drop view if exists public.v_book_request_feed;create view public.v_book_request_feed as select br.id,br.request_number,br.status,br.preferred_handover_method,br.seller_pin_code,br.total_original_price,br.total_estimated_payout,br.notes,br.created_at,case when br.assigned_stall_id=bs.id and br.status not in ('Pending','Offer Received','Offer Revised') then p.full_name else null end as seller_name,case when br.assigned_stall_id=bs.id and br.status not in ('Pending','Offer Received','Offer Revised') then p.phone_number else null end as seller_phone,case when br.assigned_stall_id=bs.id and br.status not in ('Pending','Offer Received','Offer Revised') then br.seller_address else null end as seller_address,coalesce(jsonb_agg(jsonb_build_object('id',bi.id,'title',bi.title,'author',bi.author,'isbn',bi.isbn,'category_id',bi.category_id,'class_or_semester',bi.class_or_semester,'publisher',bi.publisher,'edition',bi.edition,'original_price',bi.original_price,'condition',bi.condition,'number_of_copies',bi.number_of_copies,'estimated_item_payout',bi.estimated_item_payout,'front_cover_url',bi.front_cover_url,'back_cover_url',bi.back_cover_url,'inside_page_url',bi.inside_page_url)) filter(where bi.id is not null),'[]'::jsonb) as items from public.book_requests br join public.book_stalls bs on bs.user_id=auth.uid() and bs.admin_approval_status='approved' left join public.profiles p on p.id=br.seller_id left join public.book_items bi on bi.book_request_id=br.id where br.status in ('Pending','Offer Received','Offer Revised') or br.assigned_stall_id=bs.id group by br.id,bs.id,p.id;
drop view if exists public.v_waste_requests_recycler;create view public.v_waste_requests_recycler as select wr.id,wr.request_number,wr.paper_type,wr.estimated_weight_kg,wr.photos,wr.pickup_area,wr.pickup_pin_code,wr.preferred_pickup_date,wr.preferred_time_slot,wr.notes,wr.status,wr.created_at,case when wr.assigned_raddi_owner_id=ro.id and wr.status in ('Accepted','Pickup Scheduled','Collected','Final Price Sent','Payment Pending','Completed') then wr.seller_name else null end as seller_name,case when wr.assigned_raddi_owner_id=ro.id and wr.status in ('Accepted','Pickup Scheduled','Collected','Final Price Sent','Payment Pending','Completed') then wr.seller_phone else null end as seller_phone,case when wr.assigned_raddi_owner_id=ro.id and wr.status in ('Accepted','Pickup Scheduled','Collected','Final Price Sent','Payment Pending','Completed') then wr.pickup_address else null end as pickup_address from public.waste_requests wr left join public.raddi_owners ro on ro.user_id=auth.uid() where exists(select 1 from public.raddi_owners eligible where eligible.user_id=auth.uid() and eligible.admin_approval_status='approved');

create unique index if not exists one_book_stall_per_user on public.book_stalls(user_id);create unique index if not exists one_raddi_owner_per_user on public.raddi_owners(user_id);
-- Replace permissive initial policies. Policies are applied table by table below.
do $$ declare p record;begin for p in select schemaname,tablename,policyname from pg_policies where schemaname='public' and tablename=any(array['profiles','book_stalls','raddi_owners','categories','valuation_rules','book_requests','book_items','waste_requests','offers','payments','disputes','notifications','audit_logs','user_roles','conversations','messages','guidelines','announcements','transactions','admin_audit_logs','book_images','scrap_images']) loop execute format('drop policy if exists %I on %I.%I',p.policyname,p.schemaname,p.tablename);end loop;end $$;
alter table public.user_roles enable row level security;alter table public.conversations enable row level security;alter table public.messages enable row level security;alter table public.guidelines enable row level security;alter table public.announcements enable row level security;alter table public.transactions enable row level security;alter table public.admin_audit_logs enable row level security;alter table public.book_images enable row level security;alter table public.scrap_images enable row level security;
revoke update on public.profiles from anon,authenticated;grant select on public.profiles to authenticated;grant update(full_name,phone_number,avatar_url) on public.profiles to authenticated;
create policy profile_select on public.profiles for select to authenticated using(id=auth.uid() or public.is_admin());create policy profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy roles_self_read on public.user_roles for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy stalls_select_authorized on public.book_stalls for select to authenticated using(user_id=auth.uid() or public.is_admin() or exists(select 1 from public.offers o join public.book_requests br on br.id=o.book_request_id where o.stall_id=book_stalls.id and o.offer_status='accepted' and br.seller_id=auth.uid()));create policy stalls_signup on public.book_stalls for insert to authenticated with check(user_id=auth.uid());create policy stalls_admin_update on public.book_stalls for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy raddi_select_authorized on public.raddi_owners for select to authenticated using(user_id=auth.uid() or public.is_admin() or exists(select 1 from public.offers o join public.waste_requests wr on wr.id=o.waste_request_id where o.raddi_owner_id=raddi_owners.id and o.offer_status='accepted' and wr.seller_id=auth.uid()));create policy raddi_signup on public.raddi_owners for insert to authenticated with check(user_id=auth.uid());create policy raddi_admin_update on public.raddi_owners for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy categories_read on public.categories for select using(is_active or public.is_admin());create policy categories_admin on public.categories for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy valuation_read on public.valuation_rules for select using(true);create policy valuation_admin on public.valuation_rules for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy book_requests_party_read on public.book_requests for select to authenticated using(seller_id=auth.uid() or public.is_admin() or exists(select 1 from public.offers o join public.book_stalls bs on bs.id=o.stall_id where o.book_request_id=book_requests.id and o.offer_status='accepted' and bs.user_id=auth.uid()));create policy book_request_seller_create on public.book_requests for insert to authenticated with check(seller_id=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_verified and p.age_confirmed and p.suspended_at is null));revoke update on public.book_requests from authenticated;create policy book_request_admin_all on public.book_requests for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy book_items_party_read on public.book_items for select to authenticated using(exists(select 1 from public.book_requests br where br.id=book_request_id and (br.seller_id=auth.uid() or public.is_admin() or (br.status in ('Pending','Offer Received','Offer Revised') and exists(select 1 from public.book_stalls bs where bs.user_id=auth.uid() and bs.admin_approval_status='approved')) or exists(select 1 from public.offers o join public.book_stalls bs on bs.id=o.stall_id where o.book_request_id=br.id and o.offer_status='accepted' and bs.user_id=auth.uid()))));create policy book_items_seller_create on public.book_items for insert to authenticated with check(exists(select 1 from public.book_requests br where br.id=book_request_id and br.seller_id=auth.uid()));
create policy waste_requests_party_read on public.waste_requests for select to authenticated using(seller_id=auth.uid() or public.is_admin() or exists(select 1 from public.offers o join public.raddi_owners ro on ro.id=o.raddi_owner_id where o.waste_request_id=waste_requests.id and o.offer_status='accepted' and ro.user_id=auth.uid()));create policy waste_request_seller_create on public.waste_requests for insert to authenticated with check(seller_id=auth.uid() and estimated_weight_kg>=10 and exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_verified and p.age_confirmed and p.suspended_at is null));revoke update on public.waste_requests from authenticated;create policy waste_request_admin_all on public.waste_requests for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy offers_party_read on public.offers for select to authenticated using(public.is_admin() or exists(select 1 from public.book_requests br where br.id=book_request_id and br.seller_id=auth.uid()) or exists(select 1 from public.waste_requests wr where wr.id=waste_request_id and wr.seller_id=auth.uid()) or exists(select 1 from public.book_stalls bs where bs.id=stall_id and bs.user_id=auth.uid()) or exists(select 1 from public.raddi_owners ro where ro.id=raddi_owner_id and ro.user_id=auth.uid()));create policy offers_approved_owner_insert on public.offers for insert to authenticated with check((request_type='book' and exists(select 1 from public.book_stalls bs join public.profiles p on p.id=bs.user_id where bs.id=stall_id and bs.user_id=auth.uid() and bs.admin_approval_status='approved' and p.is_verified and p.suspended_at is null)) or (request_type='raddi' and exists(select 1 from public.raddi_owners ro join public.profiles p on p.id=ro.user_id where ro.id=raddi_owner_id and ro.user_id=auth.uid() and ro.admin_approval_status='approved' and p.is_verified and p.suspended_at is null)));revoke update on public.offers from authenticated;create policy offers_admin_all on public.offers for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy payments_party_read on public.payments for select to authenticated using(payer_user_id=auth.uid() or seller_user_id=auth.uid() or public.is_admin());create policy payments_partner_insert on public.payments for insert to authenticated with check(payer_user_id=auth.uid() and exists(select 1 from public.book_requests br where br.id=book_request_id and br.assigned_stall_id in(select id from public.book_stalls where user_id=auth.uid() and admin_approval_status='approved')) or payer_user_id=auth.uid() and exists(select 1 from public.waste_requests wr where wr.id=waste_request_id and wr.assigned_raddi_owner_id in(select id from public.raddi_owners where user_id=auth.uid() and admin_approval_status='approved')));create policy payments_admin_all on public.payments for all to authenticated using(public.is_admin()) with check(public.is_admin());revoke insert,update,delete on public.payments from authenticated;
create policy disputes_party_read on public.disputes for select to authenticated using(raised_by_user_id=auth.uid() or against_user_id=auth.uid() or public.is_admin());create policy disputes_party_insert on public.disputes for insert to authenticated with check(raised_by_user_id=auth.uid());create policy disputes_admin_update on public.disputes for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy notifications_own_read on public.notifications for select to authenticated using(user_id=auth.uid() or public.is_admin());create policy notifications_own_update on public.notifications for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy conversations_party_read on public.conversations for select to authenticated using(seller_id=auth.uid() or partner_id=auth.uid());create policy messages_party_read on public.messages for select to authenticated using(exists(select 1 from public.conversations c where c.id=conversation_id and (c.seller_id=auth.uid() or c.partner_id=auth.uid())));create policy messages_party_insert on public.messages for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from public.conversations c where c.id=conversation_id and (c.seller_id=auth.uid() or c.partner_id=auth.uid())));
create policy guidelines_public_read on public.guidelines for select using(is_published or public.is_admin());create policy guidelines_admin on public.guidelines for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy announcements_public_read on public.announcements for select using(is_published and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>now()) or public.is_admin());create policy announcements_admin on public.announcements for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy transactions_party_read on public.transactions for select to authenticated using(seller_id=auth.uid() or partner_id=auth.uid() or public.is_admin());create policy transactions_admin_all on public.transactions for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy audit_admin_read on public.admin_audit_logs for select to authenticated using(public.is_admin());create policy book_images_party_read on public.book_images for select to authenticated using(exists(select 1 from public.book_items bi join public.book_requests br on br.id=bi.book_request_id where bi.id=book_item_id and (br.seller_id=auth.uid() or public.is_admin() or br.status in ('Pending','Offer Received','Offer Revised') and exists(select 1 from public.book_stalls bs where bs.user_id=auth.uid() and bs.admin_approval_status='approved'))));create policy scrap_images_party_read on public.scrap_images for select to authenticated using(exists(select 1 from public.waste_requests wr where wr.id=waste_request_id and (wr.seller_id=auth.uid() or public.is_admin() or wr.assigned_raddi_owner_id in(select id from public.raddi_owners where user_id=auth.uid()))));

-- RPC acceptance enforces exactly one selected offer and is the only path that unlocks private details.
create or replace function public.respond_to_offer(p_offer_id uuid,p_accept boolean) returns jsonb language plpgsql security definer set search_path=public,auth as $$ declare o public.offers; seller uuid; partner uuid; reqid uuid;begin select * into o from public.offers where id=p_offer_id for update;if not found then raise exception 'Offer not found';end if;if o.request_type='book' then select seller_id into seller from public.book_requests where id=o.book_request_id for update;partner:=(select user_id from public.book_stalls where id=o.stall_id);reqid:=o.book_request_id;else select seller_id into seller from public.waste_requests where id=o.waste_request_id for update;partner:=(select user_id from public.raddi_owners where id=o.raddi_owner_id);reqid:=o.waste_request_id;end if;if seller<>auth.uid() then raise exception 'Only the seller can respond';end if;if o.offer_status not in ('active','revised') then raise exception 'Offer is no longer available';end if;if p_accept then if exists(select 1 from public.offers where request_type=o.request_type and (case when o.request_type='book' then book_request_id=o.book_request_id else waste_request_id=o.waste_request_id end) and offer_status='accepted') then raise exception 'Another offer was already selected';end if;update public.offers set offer_status='accepted',updated_at=now() where id=o.id;update public.offers set offer_status='rejected',updated_at=now() where id<>o.id and request_type=o.request_type and (case when o.request_type='book' then book_request_id=o.book_request_id else waste_request_id=o.waste_request_id end) and offer_status in ('active','revised');if o.request_type='book' then update public.book_requests set status='Accepted',assigned_stall_id=o.stall_id where id=reqid;else update public.waste_requests set status='Accepted',assigned_raddi_owner_id=o.raddi_owner_id where id=reqid;end if;insert into public.transactions(request_type,book_request_id,waste_request_id,offer_id,seller_id,partner_id,status) values(o.request_type,o.book_request_id,o.waste_request_id,o.id,seller,partner,'Accepted') on conflict do nothing;insert into public.conversations(request_type,book_request_id,waste_request_id,seller_id,partner_id) values(o.request_type,o.book_request_id,o.waste_request_id,seller,partner) on conflict do nothing;insert into public.notifications(user_id,title,message,link) values(partner,'Offer accepted','The seller accepted your offer. Contact details are now available for this transaction.','/dashboard');else update public.offers set offer_status='rejected',rejection_reason=coalesce(rejection_reason,'Seller declined'),updated_at=now() where id=o.id;insert into public.notifications(user_id,title,message,link) values(partner,'Offer declined','The seller declined your offer.','/dashboard');end if;return jsonb_build_object('accepted',p_accept,'request_type',o.request_type,'request_id',reqid);end $$;
revoke all on function public.respond_to_offer(uuid,boolean) from public;grant execute on function public.respond_to_offer(uuid,boolean) to authenticated;
create or replace function public.owner_book_progress(p_request_id uuid,p_action text,p_final_amount numeric default null,p_reason text default null) returns void language plpgsql security definer set search_path=public,auth as $$ declare br public.book_requests; st uuid; partner uuid; cap numeric;begin select * into br from public.book_requests where id=p_request_id for update;if not found then raise exception 'Request not found';end if;select id,user_id into st,partner from public.book_stalls where id=br.assigned_stall_id and admin_approval_status='approved';if partner<>auth.uid() then raise exception 'Not the selected stall';end if;if p_action='received' and br.status='Accepted' then update public.book_requests set status='Received' where id=br.id;elsif p_action='inspection' and br.status='Received' then update public.book_requests set status='Under Inspection' where id=br.id;elsif p_action='final_offer' and br.status='Under Inspection' then select coalesce(sum(estimated_item_payout),0) into cap from public.book_items where book_request_id=br.id;if p_final_amount is null or p_final_amount<=0 or p_final_amount>cap then raise exception 'Final offer exceeds the condition cap';end if;if p_final_amount<>br.total_estimated_payout and nullif(trim(p_reason),'') is null then raise exception 'A changed final offer requires a written reason';end if;update public.book_requests set status='Final Offer Sent',final_offer_amount=p_final_amount,final_offer_reason=p_reason,final_offer_accepted_at=null where id=br.id;insert into public.notifications(user_id,title,message,link) values(br.seller_id,'Final book offer received','Review the final offer and accept or decline it.','/dashboard');else raise exception 'Invalid book transaction step';end if;end $$;
revoke all on function public.owner_book_progress(uuid,text,numeric,text) from public;grant execute on function public.owner_book_progress(uuid,text,numeric,text) to authenticated;
create or replace function public.respond_to_final_offer(p_request_type text,p_request_id uuid,p_accept boolean) returns void language plpgsql security definer set search_path=public,auth as $$ declare seller uuid;partner uuid;amt numeric;begin if p_request_type='book' then select seller_id,final_offer_amount,assigned_stall_id into seller,amt,partner from public.book_requests where id=p_request_id for update;partner:=(select user_id from public.book_stalls where id=partner);if seller<>auth.uid() then raise exception 'Only the seller can respond';end if;if amt is null then raise exception 'No final offer';end if;if p_accept then update public.book_requests set final_offer_accepted_at=now(),status='Payment Pending' where id=p_request_id;else update public.book_requests set status='Disputed' where id=p_request_id;end if;else select seller_id,final_offer_amount,assigned_raddi_owner_id into seller,amt,partner from public.waste_requests where id=p_request_id for update;partner:=(select user_id from public.raddi_owners where id=partner);if seller<>auth.uid() then raise exception 'Only the seller can respond';end if;if amt is null then raise exception 'No final offer';end if;if p_accept then update public.waste_requests set final_offer_accepted_at=now(),status='Payment Pending' where id=p_request_id;else update public.waste_requests set status='Disputed' where id=p_request_id;end if;end if;insert into public.notifications(user_id,title,message,link) values(partner,case when p_accept then 'Final offer accepted' else 'Final offer declined' end,'The seller responded to the final offer.','/dashboard');end $$;
revoke all on function public.respond_to_final_offer(text,uuid,boolean) from public;grant execute on function public.respond_to_final_offer(text,uuid,boolean) to authenticated;
create or replace function public.owner_waste_progress(p_request_id uuid,p_action text,p_actual_weight numeric default null,p_final_amount numeric default null,p_reason text default null) returns void language plpgsql security definer set search_path=public,auth as $$ declare wr public.waste_requests; partner uuid;begin select * into wr from public.waste_requests where id=p_request_id for update;if not found then raise exception 'Request not found';end if;partner:=(select user_id from public.raddi_owners where id=wr.assigned_raddi_owner_id and admin_approval_status='approved');if partner<>auth.uid() then raise exception 'Not the selected raddi owner';end if;if p_action='schedule' and wr.status='Accepted' then update public.waste_requests set status='Pickup Scheduled' where id=wr.id;elsif p_action='collect' and wr.status='Pickup Scheduled' then if p_actual_weight is null or p_actual_weight<=0 then raise exception 'Actual weight must be positive';end if;update public.waste_requests set status='Collected',actual_weight_kg=p_actual_weight where id=wr.id;elsif p_action='final_offer' and wr.status='Collected' then if p_final_amount is null or p_final_amount<=0 then raise exception 'Final amount must be positive';end if;if p_actual_weight<10 and nullif(trim(p_reason),'') is null then raise exception 'Below-minimum actual weight needs a written explanation';end if;update public.waste_requests set status='Final Price Sent',final_offer_amount=p_final_amount,final_offer_reason=p_reason where id=wr.id;insert into public.notifications(user_id,title,message,link) values(wr.seller_id,'Final raddi price received','Review the final amount after weighing.','/dashboard');else raise exception 'Invalid raddi transaction step';end if;end $$;
revoke all on function public.owner_waste_progress(uuid,text,numeric,numeric,text) from public;grant execute on function public.owner_waste_progress(uuid,text,numeric,numeric,text) to authenticated;
create or replace function public.record_direct_payment(p_request_type text,p_request_id uuid,p_amount numeric,p_method text,p_reference text,p_date date,p_notes text default null) returns uuid language plpgsql security definer set search_path=public,auth as $$ declare seller uuid;partner uuid;pid uuid;begin if p_amount<=0 or p_method not in ('cash','upi','bank_transfer') then raise exception 'Invalid payment amount or method';end if;if p_request_type='book' then select br.seller_id,bs.user_id into seller,partner from public.book_requests br join public.book_stalls bs on bs.id=br.assigned_stall_id where br.id=p_request_id and br.final_offer_accepted_at is not null;else select wr.seller_id,ro.user_id into seller,partner from public.waste_requests wr join public.raddi_owners ro on ro.id=wr.assigned_raddi_owner_id where wr.id=p_request_id and wr.final_offer_accepted_at is not null;end if;if partner<>auth.uid() then raise exception 'Only the selected partner can record payment';end if;if p_request_type='book' and p_amount<>(select final_offer_amount from public.book_requests where id=p_request_id) then raise exception 'Payment must match seller-accepted final offer';elsif p_request_type='raddi' and p_amount<>(select final_offer_amount from public.waste_requests where id=p_request_id) then raise exception 'Payment must match seller-accepted final offer';end if;insert into public.payments(transaction_type,book_request_id,waste_request_id,payer_user_id,seller_user_id,amount,payment_method,payment_reference_utr,payment_date,notes,payer_recorded_at,status) values(p_request_type,case when p_request_type='book' then p_request_id end,case when p_request_type='raddi' then p_request_id end,partner,seller,p_amount,p_method,p_reference,p_date,p_notes,now(),'pending_confirmation') returning id into pid;return pid;end $$;
revoke all on function public.record_direct_payment(text,uuid,numeric,text,text,date,text) from public;grant execute on function public.record_direct_payment(text,uuid,numeric,text,text,date,text) to authenticated;
create or replace function public.confirm_payment_received(p_payment_id uuid) returns void language plpgsql security definer set search_path=public,auth as $$ declare pay public.payments;begin select * into pay from public.payments where id=p_payment_id for update;if pay.seller_user_id<>auth.uid() then raise exception 'Only the seller can confirm receipt';end if;update public.payments set seller_confirmed_at=now(),status='confirmed' where id=pay.id;if pay.transaction_type='book' then update public.book_requests set status='Completed' where id=pay.book_request_id;else update public.waste_requests set status='Completed' where id=pay.waste_request_id;end if;update public.transactions set status='Completed',updated_at=now() where (book_request_id=pay.book_request_id and pay.book_request_id is not null) or (waste_request_id=pay.waste_request_id and pay.waste_request_id is not null);insert into public.notifications(user_id,title,message,link) values(pay.payer_user_id,'Payment confirmed','Seller confirmed they received payment. Transaction completed.','/dashboard');end $$;
revoke all on function public.confirm_payment_received(uuid) from public;grant execute on function public.confirm_payment_received(uuid) to authenticated;

-- Offer and message notification triggers.
create or replace function public.notify_offer_change() returns trigger language plpgsql security definer set search_path=public as $$ declare recipient uuid;rid uuid;begin if new.request_type='book' then select seller_id into recipient from public.book_requests where id=new.book_request_id;rid:=new.book_request_id;update public.book_requests set status='Offer Received' where id=rid and status='Pending';else select seller_id into recipient from public.waste_requests where id=new.waste_request_id;rid:=new.waste_request_id;update public.waste_requests set status='Offer Received' where id=rid and status='Pending';end if;insert into public.notifications(user_id,title,message,link) values(recipient,'New offer received','A registered partner sent you an offer.','/dashboard');return new;end $$;
drop trigger if exists notify_offer_insert on public.offers;create trigger notify_offer_insert after insert on public.offers for each row execute function public.notify_offer_change();
create or replace function public.notify_new_message() returns trigger language plpgsql security definer set search_path=public as $$ declare target uuid;begin select case when seller_id=new.sender_id then partner_id else seller_id end into target from public.conversations where id=new.conversation_id;insert into public.notifications(user_id,title,message,link) values(target,'New message','You have a new transaction message.','/dashboard');return new;end $$;
drop trigger if exists message_notification on public.messages;create trigger message_notification after insert on public.messages for each row execute function public.notify_new_message();
create or replace function public.write_admin_audit() returns trigger language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Admin only';end if;insert into public.admin_audit_logs(admin_id,action,entity_type,entity_id,details) values(auth.uid(),tg_argv[0],tg_table_name,coalesce(new.id,old.id),case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end);return coalesce(new,old);end $$;

-- Storage remains private; user paths begin with the authenticated user id.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('secondshelf-private','secondshelf-private',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
create policy ss_upload_own on storage.objects for insert to authenticated with check(bucket_id='secondshelf-private' and (storage.foldername(name))[1]=auth.uid()::text and lower(storage.extension(name)) in ('jpg','jpeg','png','webp'));
create policy ss_delete_own on storage.objects for delete to authenticated using(bucket_id='secondshelf-private' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.can_read_private_upload(p_name text) returns boolean language sql stable security definer set search_path=public,auth as $$
select (storage.foldername(p_name))[1]=auth.uid()::text or public.is_admin()
or exists(select 1 from public.book_items bi join public.book_requests br on br.id=bi.book_request_id where p_name in (bi.front_cover_url,bi.back_cover_url,bi.inside_page_url) and (br.seller_id=auth.uid() or exists(select 1 from public.book_stalls bs where bs.user_id=auth.uid() and bs.admin_approval_status='approved' and (br.status in ('Pending','Offer Received','Offer Revised') or br.assigned_stall_id=bs.id))))
or exists(select 1 from public.waste_requests wr where p_name=any(wr.photos) and (wr.seller_id=auth.uid() or exists(select 1 from public.raddi_owners ro where ro.user_id=auth.uid() and ro.admin_approval_status='approved' and (wr.status in ('Pending','Offer Received') or wr.assigned_raddi_owner_id=ro.id))));$$;
create policy ss_read_participant on storage.objects for select to authenticated using(bucket_id='secondshelf-private' and public.can_read_private_upload(name));

-- Realtime publishes only user-scoped notifications, messages and offers.
create or replace function public.admin_set_user_suspended(p_user_id uuid,p_suspended boolean) returns void language plpgsql security definer set search_path=public,auth as $$ begin if not public.is_admin() then raise exception 'Admin only';end if;if p_user_id=auth.uid() then raise exception 'Admin cannot suspend own account';end if;update public.profiles set suspended_at=case when p_suspended then now() else null end where id=p_user_id and role<>'admin';if not found then raise exception 'User not found or not suspendable';end if;end $$;revoke all on function public.admin_set_user_suspended(uuid,boolean) from public;grant execute on function public.admin_set_user_suspended(uuid,boolean) to authenticated;
create policy legacy_audit_admin_read on public.audit_logs for select to authenticated using(public.is_admin());
create trigger audit_stall_approval after update on public.book_stalls for each row when(old.admin_approval_status is distinct from new.admin_approval_status) execute function public.write_admin_audit('business approval');
create trigger audit_raddi_approval after update on public.raddi_owners for each row when(old.admin_approval_status is distinct from new.admin_approval_status) execute function public.write_admin_audit('business approval');
create trigger audit_valuation_change after update on public.valuation_rules for each row execute function public.write_admin_audit('valuation rule update');
create trigger audit_category_change after insert or update or delete on public.categories for each row execute function public.write_admin_audit('category change');
create trigger audit_dispute_change after update on public.disputes for each row execute function public.write_admin_audit('dispute update');create or replace function public.cancel_own_request(p_request_type text,p_request_id uuid) returns void language plpgsql security definer set search_path=public,auth as $$ declare seller uuid;st text;actual numeric;begin if p_request_type='book' then select seller_id,status into seller,st from public.book_requests where id=p_request_id for update;if seller<>auth.uid() then raise exception 'Not your request';end if;if st not in ('Pending','Offer Received','Offer Revised','Accepted','Awaiting Book') then raise exception 'This request can no longer be cancelled';end if;update public.book_requests set status='Cancelled' where id=p_request_id;else select seller_id,status,actual_weight_kg into seller,st,actual from public.waste_requests where id=p_request_id for update;if seller<>auth.uid() then raise exception 'Not your request';end if;if st not in ('Pending','Offer Received','Accepted','Pickup Scheduled','Collected','Final Price Sent') then raise exception 'This request can no longer be cancelled';end if;if actual is not null and actual>=10 and st in ('Collected','Final Price Sent') then raise exception 'Cancellation without penalty is only available when measured weight is below 10 kg';end if;update public.waste_requests set status='Cancelled' where id=p_request_id;end if;end $$;
revoke all on function public.cancel_own_request(text,uuid) from public;grant execute on function public.cancel_own_request(text,uuid) to authenticated;
create or replace function public.admin_set_business_status(p_type text,p_business_id uuid,p_status text,p_reason text default null) returns void language plpgsql security definer set search_path=public,auth as $$ begin if not public.is_admin() then raise exception 'Admin only';end if;if p_status not in ('approved','rejected','suspended','pending') then raise exception 'Invalid status';end if;if p_type='stall' then update public.book_stalls set admin_approval_status=p_status,rejection_reason=p_reason where id=p_business_id;elsif p_type='raddi' then update public.raddi_owners set admin_approval_status=p_status,rejection_reason=p_reason where id=p_business_id;else raise exception 'Invalid business type';end if;if not found then raise exception 'Business not found';end if;end $$;
revoke all on function public.admin_set_business_status(text,uuid,text,text) from public;grant execute on function public.admin_set_business_status(text,uuid,text,text) to authenticated;
create or replace function public.notify_new_request() returns trigger language plpgsql security definer set search_path=public as $$ declare u record;begin if tg_table_name='book_requests' then for u in select user_id from public.book_stalls where admin_approval_status='approved' loop insert into public.notifications(user_id,title,message,link) values(u.user_id,'New book request','A new book request is available for review.','/dashboard');end loop;else for u in select user_id from public.raddi_owners where admin_approval_status='approved' loop insert into public.notifications(user_id,title,message,link) values(u.user_id,'New waste paper request','A new eligible waste paper request is available.','/dashboard');end loop;end if;return new;end $$;
drop trigger if exists notify_new_book_request on public.book_requests;create trigger notify_new_book_request after insert on public.book_requests for each row execute function public.notify_new_request();drop trigger if exists notify_new_waste_request on public.waste_requests;create trigger notify_new_waste_request after insert on public.waste_requests for each row execute function public.notify_new_request();
grant select on public.v_book_request_feed,public.v_waste_requests_recycler to authenticated;
alter table public.notifications replica identity full;alter table public.messages replica identity full;alter table public.offers replica identity full;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications') then alter publication supabase_realtime add table public.notifications;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='messages') then alter publication supabase_realtime add table public.messages;end if;if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='offers') then alter publication supabase_realtime add table public.offers;end if;end $$;


-- Additional integrity guards and rollups required by the live forms.
insert into public.user_roles(user_id,role) select id,role from public.profiles on conflict(user_id) do update set role=excluded.role;
create or replace function public.create_profile_from_auth() returns trigger language plpgsql security definer set search_path=public,auth as $$
declare requested_role text; business_name text; business_address text; business_pin text; business_license text; phone text;
begin
 requested_role:=coalesce(new.raw_user_meta_data->>'role','seller');
 if requested_role not in ('seller','book_stall','raddi_owner') then raise exception 'Public registration cannot create this role'; end if;
 if new.raw_user_meta_data->>'age_confirmed' is distinct from 'true' then raise exception 'You must confirm you are at least 18 years old'; end if;
 phone:=nullif(trim(new.raw_user_meta_data->>'phone_number'),'');
 if phone is null or nullif(trim(new.raw_user_meta_data->>'full_name'),'') is null then raise exception 'Name and phone are required'; end if;
 business_name:=nullif(trim(new.raw_user_meta_data->>'business_name'),''); business_address:=nullif(trim(new.raw_user_meta_data->>'business_address'),''); business_pin:=nullif(trim(new.raw_user_meta_data->>'business_pin'),''); business_license:=nullif(trim(new.raw_user_meta_data->>'business_license'),'');
 if requested_role<>'seller' and (business_name is null or business_address is null or business_pin !~ '^[1-9][0-9]{5}$') then raise exception 'Complete valid business registration details'; end if;
 insert into public.profiles(id,email,full_name,phone_number,role,is_verified,age_confirmed) values(new.id,new.email,trim(new.raw_user_meta_data->>'full_name'),phone,requested_role,new.email_confirmed_at is not null,true);
 insert into public.user_roles(user_id,role) values(new.id,requested_role);
 if requested_role='book_stall' then insert into public.book_stalls(user_id,stall_name,shop_licence_or_gst,address,pin_code,contact_phone,contact_email,admin_approval_status) values(new.id,business_name,business_license,business_address,business_pin,phone,new.email,'pending');
 elsif requested_role='raddi_owner' then insert into public.raddi_owners(user_id,business_name,licence_number,base_address,operating_pin_codes,contact_phone,contact_email,admin_approval_status) values(new.id,business_name,business_license,business_address,array[business_pin],phone,new.email,'pending'); end if;
 return new;
end $$;
create or replace function public.recalculate_book_request_totals() returns trigger language plpgsql security definer set search_path=public as $$
declare rid uuid;
begin rid:=coalesce(new.book_request_id,old.book_request_id); update public.book_requests br set total_original_price=x.original_total,total_estimated_payout=x.estimate from (select coalesce(sum(original_price*number_of_copies),0) original_total,coalesce(sum(estimated_item_payout),0) estimate from public.book_items where book_request_id=rid) x where br.id=rid;return coalesce(new,old);end $$;
drop trigger if exists book_request_totals on public.book_items;
create trigger book_request_totals after insert or update or delete on public.book_items for each row execute function public.recalculate_book_request_totals();
create or replace function public.write_admin_audit() returns trigger language plpgsql security definer set search_path=public as $$
begin if not public.is_admin() then raise exception 'Admin only';end if;insert into public.admin_audit_logs(admin_id,action,entity_type,entity_id,details) values(auth.uid(),tg_argv[0],tg_table_name,case when tg_op='DELETE' then old.id else new.id end,case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end);if tg_op='DELETE' then return old;else return new;end if;end $$;


-- Sellers can replace their own uploaded image paths after private storage uploads.
grant update(front_cover_url,back_cover_url,inside_page_url) on public.book_items to authenticated;
create policy book_items_seller_image_update on public.book_items for update to authenticated using(exists(select 1 from public.book_requests br where br.id=book_request_id and br.seller_id=auth.uid())) with check(exists(select 1 from public.book_requests br where br.id=book_request_id and br.seller_id=auth.uid()));

-- SECURITY DEFINER membership helpers avoid cyclic RLS subqueries among requests, offers and owners.
create or replace function public.seller_has_stall_offer(p_stall_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.offers o join public.book_requests br on br.id=o.book_request_id where o.stall_id=p_stall_id and br.seller_id=auth.uid()) $$;
create or replace function public.seller_has_raddi_offer(p_owner_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.offers o join public.waste_requests wr on wr.id=o.waste_request_id where o.raddi_owner_id=p_owner_id and wr.seller_id=auth.uid()) $$;
create or replace function public.is_selected_stall_request(p_request_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.book_requests br join public.book_stalls bs on bs.id=br.assigned_stall_id where br.id=p_request_id and bs.user_id=auth.uid() and bs.admin_approval_status='approved') $$;
create or replace function public.is_selected_raddi_request(p_request_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.waste_requests wr join public.raddi_owners ro on ro.id=wr.assigned_raddi_owner_id where wr.id=p_request_id and ro.user_id=auth.uid() and ro.admin_approval_status='approved') $$;
create or replace function public.is_approved_stall(p_stall_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.book_stalls bs join public.profiles p on p.id=bs.user_id where bs.id=p_stall_id and bs.user_id=auth.uid() and bs.admin_approval_status='approved' and p.is_verified and p.suspended_at is null) $$;
create or replace function public.is_approved_raddi_owner(p_owner_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.raddi_owners ro join public.profiles p on p.id=ro.user_id where ro.id=p_owner_id and ro.user_id=auth.uid() and ro.admin_approval_status='approved' and p.is_verified and p.suspended_at is null) $$;
create or replace function public.can_read_offer(p_offer_id uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.offers o left join public.book_requests br on br.id=o.book_request_id left join public.waste_requests wr on wr.id=o.waste_request_id left join public.book_stalls bs on bs.id=o.stall_id left join public.raddi_owners ro on ro.id=o.raddi_owner_id where o.id=p_offer_id and (public.is_admin() or br.seller_id=auth.uid() or wr.seller_id=auth.uid() or bs.user_id=auth.uid() or ro.user_id=auth.uid())) $$;
revoke all on function public.seller_has_stall_offer(uuid),public.seller_has_raddi_offer(uuid),public.is_selected_stall_request(uuid),public.is_selected_raddi_request(uuid),public.is_approved_stall(uuid),public.is_approved_raddi_owner(uuid),public.can_read_offer(uuid) from public;
grant execute on function public.seller_has_stall_offer(uuid),public.seller_has_raddi_offer(uuid),public.is_selected_stall_request(uuid),public.is_selected_raddi_request(uuid),public.is_approved_stall(uuid),public.is_approved_raddi_owner(uuid),public.can_read_offer(uuid) to authenticated;
drop policy stalls_select_authorized on public.book_stalls;create policy stalls_select_authorized on public.book_stalls for select to authenticated using(user_id=auth.uid() or public.is_admin() or public.seller_has_stall_offer(id));
drop policy raddi_select_authorized on public.raddi_owners;create policy raddi_select_authorized on public.raddi_owners for select to authenticated using(user_id=auth.uid() or public.is_admin() or public.seller_has_raddi_offer(id));
drop policy book_requests_party_read on public.book_requests;create policy book_requests_party_read on public.book_requests for select to authenticated using(seller_id=auth.uid() or public.is_admin() or public.is_selected_stall_request(id));
drop policy waste_requests_party_read on public.waste_requests;create policy waste_requests_party_read on public.waste_requests for select to authenticated using(seller_id=auth.uid() or public.is_admin() or public.is_selected_raddi_request(id));
drop policy offers_party_read on public.offers;create policy offers_party_read on public.offers for select to authenticated using(public.can_read_offer(id));
drop policy offers_approved_owner_insert on public.offers;create policy offers_approved_owner_insert on public.offers for insert to authenticated with check((request_type='book' and public.is_approved_stall(stall_id)) or (request_type='raddi' and public.is_approved_raddi_owner(raddi_owner_id)));

alter table public.book_requests add constraint book_seller_pin_six_digits check(seller_pin_code ~ '^[1-9][0-9]{5}$');
alter table public.waste_requests add constraint waste_pin_six_digits check(pickup_pin_code ~ '^[1-9][0-9]{5}$');
create or replace function public.mark_conversation_read(p_conversation_id uuid) returns void language plpgsql security definer set search_path=public,auth as $$
begin if not exists(select 1 from public.conversations where id=p_conversation_id and (seller_id=auth.uid() or partner_id=auth.uid())) then raise exception 'Not a conversation participant';end if;update public.messages set read_at=now() where conversation_id=p_conversation_id and sender_id<>auth.uid() and read_at is null;end $$;
revoke all on function public.mark_conversation_read(uuid) from public;grant execute on function public.mark_conversation_read(uuid) to authenticated;
commit;
